import{_ as t,o as d,c as r,a2 as c}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"过滤器","description":"","frontmatter":{},"headers":[],"relativePath":"docs/rules/filters.md","filePath":"docs/rules/filters.md"}'),o={name:"docs/rules/filters.md"};function l(a,e,i,n,p,s){return d(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="过滤器" tabindex="-1">过滤器 <a class="header-anchor" href="#过滤器" aria-label="Permalink to &quot;过滤器&quot;">​</a></h1><p>当需要基于请求属性或响应属性（而不仅仅是URL）进行匹配时，可以使用过滤器来实现更精细化的规则控制，语法结构：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pattern opertaion includeFilter://pattern1 ... excludeFilter://patternx ...</span></span></code></pre></div><blockquote><p>多个过滤器间为「或」匹配，只要匹配其中一个过滤条件就成立</p></blockquote><h2 id="过滤器类型" tabindex="-1">过滤器类型 <a class="header-anchor" href="#过滤器类型" aria-label="Permalink to &quot;过滤器类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>过滤器类型</th><th>语法格式</th><th>用途</th></tr></thead><tbody><tr><td><strong>包含过滤器</strong></td><td><code>includeFilter://pattern</code></td><td>只匹配符合指定条件的请求</td></tr><tr><td><strong>排除过滤器</strong></td><td><code>excludeFilter://pattern</code></td><td>排除符合指定条件的请求</td></tr></tbody></table><h2 id="pattern-类型" tabindex="-1">pattern 类型 <a class="header-anchor" href="#pattern-类型" aria-label="Permalink to &quot;pattern 类型&quot;">​</a></h2><p>用于 <code>includeFilter://&lt;pattern&gt;</code> 和 <code>excludeFilter://&lt;pattern&gt;</code> 的匹配表达式。</p><blockquote><p><strong>通用规则</strong></p><ul><li>未指定前缀时，默认匹配请求 URL。</li><li>关键字匹配默认不区分大小写。</li><li>正则格式为 <code>/regexp/</code>，末尾可加 <code>i</code> 表示忽略大小写，例如 <code>/regexp/i</code>。</li><li><code>chance</code> 的 <code>probability</code> 取值范围为 <code>0 ~ 1</code>。</li></ul></blockquote><table tabindex="0"><thead><tr><th>语法</th><th>匹配目标</th><th>示例</th></tr></thead><tbody><tr><td><code>b:pattern</code></td><td>请求体内容：关键字（不区分大小写）或正则</td><td><code>includeFilter://b:keyword</code><br><code>excludeFilter://b:/regexp/i</code></td></tr><tr><td><code>m:pattern</code></td><td>HTTP 方法：方法名（不区分大小写）或正则</td><td><code>includeFilter://m:get</code><br><code>excludeFilter://m:/regexp/i</code></td></tr><tr><td><code>i:pattern</code></td><td>客户端或服务端 IP：IP 或正则</td><td><code>includeFilter://i:192.168.1.10</code><br><code>excludeFilter://i:/regexp/i</code></td></tr><tr><td><code>chance:probability</code></td><td>按概率随机命中：<code>Math.random() &lt; probability</code></td><td><code>includeFilter://chance:0.5</code><br><code>excludeFilter://chance:0.3</code></td></tr><tr><td><code>clientIp:pattern</code></td><td>客户端 IP：IP 或正则</td><td><code>includeFilter://clientIp:192.168.1.10</code><br><code>excludeFilter://clientIp:/regexp/i</code></td></tr><tr><td><code>serverIp:pattern</code></td><td>服务端 IP：IP 或正则</td><td><code>includeFilter://serverIp:192.168.1.10</code><br><code>excludeFilter://serverIp:/regexp/i</code></td></tr><tr><td><code>s:pattern</code></td><td>响应状态码：状态码或正则</td><td><code>includeFilter://s:/^20/</code><br><code>excludeFilter://s:200</code></td></tr><tr><td><code>reqH.header-key:pattern</code></td><td>请求头：关键字（不区分大小写）或正则</td><td><code>includeFilter://reqH.content-type:json</code><br><code>excludeFilter://reqH.content-type:/regexp/i</code></td></tr><tr><td><code>resH.header-key:pattern</code></td><td>响应头：关键字（不区分大小写）或正则</td><td><code>includeFilter://resH.content-type:json</code><br><code>excludeFilter://resH.content-type:/regexp/i</code></td></tr><tr><td>无前缀 <code>pattern</code>（其它 <code>xxxxxx</code>）</td><td>请求 URL，同 <a href="./pattern.html">pattern</a></td><td><code>includeFilter://*/cgi-*</code><br><code>excludeFilter://www.test.com</code><br><code>includeFilter://https://www.test.com/path</code></td></tr></tbody></table>',10)])])}const b=t(o,[["render",l]]);export{h as __pageData,b as default};
